    steps = ARRAY['تونس، المغرب، الجزائر: قابلة للتحويل ✅', 'سوريا، العراق، مصر، الأردن، لبنان، الخليج: غير قابلة للتحويل ❌', 'القيادة برخصة أجنبية: 6 أشهر فقط من دخولك تركيا', 'للمؤهّلين: التحويل إداري بـ~10,500-12,000 ل.ت', 'لغير المؤهّلين: رخصة من الصفر بـ~32,000 ل.ت (3 أشهر)', 'تحقق هل بلد رخصتك ضمن الدول القابلة للتحويل وفق النظام الحالي.']::text[],
    tips = ARRAY['الرخصة السورية غير معترف بها — لا تقد بها حتى ليوم واحد', 'الامتحان النظري بالعربية متاح — لا تخف من اللغة', 'بعض مدارس القيادة تقدم دروساً بالعربية في الولايات الجنوبية', 'احتفظ بكل الترجمات المحلّفة — قد تحتاجها في مرات أخرى', 'تحقق من حالة بلدك على القائمة قبل الذهاب لـ NVI', 'لا تعتمد على معلومات قديمة عن “الدول المسموحة” لأنها تتغير.', 'قبل الموعد: تأكد أن عنوانك مثبت في النفوس لتجنب رفض الإجراء.']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'license-conversion-arab-countries-2026';

