-- car-registration  ←  4 صفحة
UPDATE articles SET
    documents = ARRAY['إقامة سارية أو كملك', 'جواز سفر + نسخة', 'الرقم الضريبي التركي', 'وثيقة تسجيل السيارة الحالية (من البائع)', 'تقرير الفحص الدوري (Muayene) ساري', 'وثيقة التأمين الإلزامي']::text[],
    steps = ARRAY['احصل على رقم ضريبي من مكتب الضرائب (Vergi Dairesi)', 'اختر السيارة وافحصها عند ميكانيكي', 'تحقق من تاريخ السيارة عبر الإنترنت (مخالفات، حوادث، رهونات)', 'اتفق مع البائع وحدد موعداً في مديرية الطابو أو النوتر', 'أصدر تأمين إلزامي (Zorunlu) باسمك', 'أتمم نقل الملكية ودفع الرسوم', 'استلم وثيقة التسجيل الجديدة (Ruhsat)', 'استعلم عن أي حجز/رهن قبل التوقيع.', 'اسأل البائع/الخبير: من يحق له قيادة السيارة؟ وهل عليها قيود خاصة؟', 'تحقق من فترة الاستحقاق الحالية (يناير/يوليو).']::text[],
    tips = ARRAY['افحص السيارة عند ميكانيكي مستقل قبل الشراء', 'تحقق أن السيارة ليس عليها رهن أو حجز عبر e-Devlet', 'لا تدفع المبلغ كاملاً قبل إتمام نقل الملكية رسمياً', 'التأمين الشامل (Kasko) يحميك من الحوادث والسرقة', 'احتفظ بجميع إيصالات الدفع والعقود', 'اسأل عن تكلفة سنوية تقريبية: تأمين + ضرائب + صيانة حتى لا تتفاجأ.', 'تجنب أي “بيع بدون نوتر” لأنه قد يعرّضك للاحتيال.']::text[],
