-- tramer-hasar-kaydi-kilometre-kontrol-turkiye-2026  ←  1 صفحة
UPDATE articles SET
    documents = ARRAY['رقم لوحة السيارة (Plaka)', 'رقم الشاسيه (Şasi / VIN) للاستعلام الدقيق', 'حساب e-Devlet وكلمة مروره (للاستعلام المجاني عن سيارة مسجَّلة باسمك)', 'هاتف بخط تركي فعّال (Turkcell / Türk Telekom / Vodafone) لإرسال SMS إلى 5664', 'تقرير الفحص الفني الدوري (TÜVTÜRK) لتاريخ السيارة', 'تقرير خبير مستقل (ekspertiz raporu) عن حالة السيارة والكيلومترات']::text[],
    steps = ARRAY['اطلب من البائع رقم اللوحة (Plaka) ورقم الشاسيه (Şasi) قبل أي شيء.', 'أرسل استعلام تاريخ الأضرار عبر SMS إلى الرقم 5664 من موقع SBM (خدمة مدفوعة، تحقّق من الصيغة والرسم الرسمي الحالي).', 'إن كانت السيارة باسم البائع، اطلب منه الدخول إلى e-Devlet وفتح خدمة (Trafik Poliçe ve Hasar Bilgileri Sorgulama) وإراءتك الشاشة مجاناً.', 'خذ السيارة إلى مركز فحص مستقل (ekspertiz) للحصول على تقرير يشمل الأضرار والأجزاء المبدَّلة ومعلومات الكيلومترات.', 'قارِن قراءة العداد الحالية مع أرقام الكيلومترات في تقارير TÜVTÜRK القديمة وتقرير الخبير؛ أي رقم أقدم أعلى من الحالي يعني تلاعباً.', 'إن ظهر تلاعب أو أضرار كبيرة غير مُعلَنة، تراجع عن الشراء أو أعِد التفاوض واحتفظ بكل الوثائق.', 'اختر مركز فحص معروف واطلب تقريراً مكتوباً.']::text[],
    tips = ARRAY['سجل Tramer مرتبط بالسيارة (اللوحة/الشاسيه) لا بالمالك، فيكشف حوادث السيارة حتى مع تغيّر أصحابها.', 'الاستعلام عبر e-Devlet مجاني لكنه للسيارات المسجَّلة باسمك؛ لسيارة تريد شراءها استعمل SMS من 5664 أو استعلام البائع أمامك.', 'بيانات الأضرار في النظام تعود لعام 2003 فصاعداً، وقد لا يظهر حادث حديث جداً فوراً لأن الإدراج يستغرق وقتاً بعد اعتماد تقرير الخبير.', 'رقم العداد لا يظهر في Tramer نفسه؛ اكشف التلاعب بمقارنة تقارير TÜVTÜRK والفحص المستقل (ekspertiz).', 'شراء السيارة من تاجر مرخّص يمنحك ضماناً قانونياً وتقرير خبير إلزامياً، بخلاف الشراء من فرد.', 'احتفظ بنسخة من الإعلان وعقد البيع؛ فإن ثبت لاحقاً غش الكيلومترات فهي دليلك لفسخ البيع أو التعويض.', 'إذا كانت هناك إصلاحات هيكلية كبيرة، فكر مرتين.']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'tramer-hasar-kaydi-kilometre-kontrol-turkiye-2026';

