    steps = ARRAY['الاستعلام عن المخالفات: ادخل e-Devlet → بحث: "Trafik Cezası"', 'الدفع عبر الإنترنت: e-Devlet → الدفع الإلكتروني', 'الاعتراض: خلال 15 يوماً من التبليغ عبر المحكمة أو PTT', 'خصم 25% عند الدفع خلال 15 يوماً من صدور المخالفة', 'حدّد نوع الإجراء: غرامة فقط أم سحب رخصة/منع قيادة.']::text[],
    tips = ARRAY['ادفع المخالفة خلال 15 يوماً واحصل على خصم 25%', 'فعّل تنبيهات المخالفات في تطبيق e-Devlet', 'الكاميرات موجودة حتى في الشوارع الصغيرة', 'حتى الراكب الأمامي يجب أن يربط حزام الأمان', 'تأكد من وجود مثلث التحذير وطفاية الحريق في السيارة (إلزامي)', 'عند الشك، استشر مختصاً لأن المهل القانونية مهمة.']::text[],
    last_update = CURRENT_DATE
