-- إسناد صفحة اللوحة إلى قانونها ------------------------------------------
UPDATE articles SET source = 'القانون رقم 7574 المعدِّل لقانون المرور على الطرق البرية — نافذاً من 27 شباط/فبراير 2026. والغرامات المذكورة هي المقادير الإدارية المقرّرة لاستعمال لوحة غير عائدة للمركبة أو لوحة مزوّرة، أو لجعل اللوحة غير مقروءة عمداً.', last_update = CURRENT_DATE
WHERE slug = 'app-plate-turkey' AND coalesce(trim(source), '') = '';

-- الخصم والتاريخ ---------------------------------------------------------
UPDATE articles SET details = coalesce(details, '') || '<div style="margin-top:1.25rem;padding:1rem;border-radius:0.75rem;border:1px solid #fcd34d;background:#fffbeb;"><p style="margin:0 0 .5rem 0;"><strong>خصم الدفع المبكر — 35,000 ليرة توفّرها:</strong> الدفع خلال خمسة عشر يوماً من التبليغ يخفّض الغرامة من 140,000 إلى <strong>105,000 ليرة</strong> بموجب خصم الدفع المبكر القانوني. ومن يذكر الغرامة ولا يذكر الخصم يكلّفك الفرق.</p><p style="margin:0;"><strong>ومتى تسري؟</strong> هذه العقوبات جاءت بالقانون رقم 7574 المعدِّل لقانون المرور، ونفاذه من <strong>27 شباط/فبراير 2026</strong>. فإن قرأت في أي مكان تاريخاً لاحقاً، تعامل مع العقوبات على أنّها سارية الآن — الأمان هنا في الافتراض الأشدّ لا الأخفّ. ومخالفة اللوحة قد تُفتح معها ملاحقة جزائية بتهمة تزوير وثيقة رسمية، وهي أثقل من الغرامة نفسها.</p></div>', last_update = CURRENT_DATE
WHERE slug = 'app-plate-turkey' AND coalesce(details, '') NOT LIKE '%7574%';

-- الصفحات المدموجة تُحذف بعد نقل ما يستحقّ
DELETE FROM articles WHERE slug IN ('auto-ehliyet-new-from-zero', 'driver-theory-prep', 'auto-ehliyet-conversion', 'driving-license', 'lost-driving-license', 'buying-car-foreigner', 'auto-noter-satis-transfer', 'auto-plates-foreigner-m-plaka', 'auto-mtv-payment', 'auto-ekspertiz-guide', 'tuvturk-appointment', 'auto-license-suspension-points-alcohol');

-- ═══════════════════════════════════════════════════════════════════════════
-- التحقّق — الأول 7 صفوف، والثاني صفر، والثالث صفّ واحد كله true
SELECT slug, coalesce(array_length(steps,1),0) AS steps,
       coalesce(array_length(tips,1),0) AS tips, last_update
FROM articles WHERE slug IN ('theory-exam-arabic-2026', 'license-conversion-arab-countries-2026', 'driving-license-fees-2026', 'car-registration', 'tramer-hasar-kaydi-kilometre-kontrol-turkiye-2026', 'auto-tuvturk-inspection', 'traffic-fines') ORDER BY slug;

SELECT slug FROM articles WHERE slug IN ('auto-ehliyet-new-from-zero', 'driver-theory-prep', 'auto-ehliyet-conversion', 'driving-license', 'lost-driving-license', 'buying-car-foreigner', 'auto-noter-satis-transfer', 'auto-plates-foreigner-m-plaka', 'auto-mtv-payment', 'auto-ekspertiz-guide', 'tuvturk-appointment', 'auto-license-suspension-points-alcohol');

SELECT slug,
       (coalesce(trim(source), '') <> '')     AS له_مصدر,
       (details LIKE '%7574%')              AS يذكر_القانون,
       (details LIKE '%105,000%')           AS يذكر_الخصم
FROM articles WHERE slug = 'app-plate-turkey';
